// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed parameters: address from (actor initiating the transfer logical origin) and an array tos
    // We need at least one fuzzed parameter; choose bytes memory encoded recipients so fuzzer can produce empty array
    function testFuzz_property(address from, bytes memory tosEncoded) public {
        // Interpret tosEncoded as ABI-encoded dynamic array of addresses.
        // If decoding fails or has unexpected length, treat as empty array.
        address[] memory tos;
        if (tosEncoded.length == 0) {
            // keep tos empty
            tos = new address[](0);
        } else {
            // try decoding; use try/catch to avoid reverts bubbling.
            try this.decodeAddrArray(tosEncoded) returns (address[] memory decoded) {
                tos = decoded;
            } catch {
                // malformed encoding -> treat as empty
                tos = new address[](0);
            }
        }

        // The general property we assert is that the reference implementation reverts when tos.length == 0.
        // We therefore call transfer in a try/catch and set ok flag accordingly.
        bool ok;
        try c.transfer(from, address(0x123), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract requires _tos.length > 0, so for ALL inputs the following holds:
        //   ok == (tos.length > 0)
        // i.e., it succeeds iff tos is non-empty. The mutant with require(_tos.length >= 0) will succeed
        // also for empty tos, breaking this property for some input (empty array).
        assertTrue(ok == (tos.length > 0));
    }

    // helper to attempt decoding an address[] from arbitrary bytes; placed in this contract so fuzzer can call it
    function decodeAddrArray(bytes memory b) external pure returns (address[] memory) {
        return abi.decode(b, (address[]));
    }
}
